SourceCode.Declaration:
/// <summary>
/// Extension of <c>CustInvoiceJour</c> to trigger the free text invoice posted business event.
/// </summary>
[ExtensionOf(tableStr(CustInvoiceJour))]
final class AAXCustInvoiceJour_Table_Extension
{
}

Method.Source:
/// <summary>
/// Triggers the free text invoice posted business event when a non-sales-order invoice is posted.
/// </summary>
void insert()
{
    next insert();

    if (!this.SalesId)
    {
        if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(AAXFreeTextInvoicePostedBusinessEvent)))
        {
            AAXFreeTextInvoicePostedBusinessEvent::newFromCustInvoiceJour(this).send();
        }
    }
}
